BEGIN;
DO $qa$
DECLARE spec jsonb:='{"order_repeat_addition":{"screen":"orders","keys":["order_toggle_reject","order_open_addition","order_late_addition","order_cancel_addition","order_invoice_addition","order_invoice_late"],"styleOnly":true},"driver_addition_actions":{"screen":"driver","keys":["driver_accept_addition","driver_reject_addition","driver_pickup_addition"],"styleOnly":true},"cashier_repeat_actions":{"screen":"cashier","keys":["cashier_receive","cashier_invoice","cashier_burger","cashier_invoice_addition","cashier_invoice_late"],"styleOnly":true},"assembly_filters":{"screen":"assembly","keys":["assembly_filter_all","assembly_filter_printed","assembly_filter_preparing","assembly_filter_ready","assembly_filter_late","assembly_filter_priority"],"styleOnly":true},"burger_filters":{"screen":"burger_kitchen","keys":["burger_filter_all","burger_filter_sent","burger_filter_preparing","burger_filter_late"],"styleOnly":true},"burger_timer":{"screen":"burger_kitchen","keys":["burger_order_timer"],"styleOnly":true},"staff_repeat_actions":{"screen":"staff","keys":["staff_toggle","staff_assembly_save","staff_assembly_convert","staff_edit","staff_save_access","staff_permission_save"],"styleOnly":true},"message_repeat_actions":{"screen":"messages","keys":["message_ack","message_read"],"styleOnly":true},"case_repeat_actions":{"screen":"cases","keys":["case_open"],"styleOnly":true},"finance_repeat_actions":{"screen":"finance","keys":["settlement_select"],"styleOnly":true},"system_repeat_actions":{"screen":"system","keys":["qa_case_save"],"styleOnly":true},"reservation_repeat_actions":{"screen":"reservations","keys":["reservation_next","reservation_cancel"],"styleOnly":true},"order_transfer_repeat":{"screen":"orders","keys":["transfer_confirm"],"styleOnly":true},"order_changes_repeat":{"screen":"orders","keys":["change_approve","change_reject","change_service","change_pos"],"styleOnly":true},"catalog_repeat_actions":{"screen":"catalog","keys":["catalog_item_edit","catalog_item_toggle","catalog_offer_edit","catalog_offer_toggle"],"styleOnly":true},"customer_repeat_actions":{"screen":"customers","keys":["customer_open"],"styleOnly":true},"driver_route_repeat":{"screen":"driver","keys":["route_edit"],"styleOnly":true},"dashboard_lifecycle_repeat":{"screen":"dashboard","keys":["lifecycle_action"],"styleOnly":true},"dashboard_watch_repeat":{"screen":"dashboard","keys":["watch_tab","watch_find"],"styleOnly":true},"report_more_controls":{"screen":"reports","keys":["ff76Close","ff76Today","ff76Yesterday","ff76Seven","ff76Thirty","ff76CSV","ff76SavePreset","ff76UsePreset","ffA10GrantSave","ff76SaveApproval"],"styleOnly":true},"report_preview_controls":{"screen":"reports","keys":["ff76DlgDownload","ff76DlgShare","ff76DlgClose"],"styleOnly":true},"message_template_controls":{"screen":"messages","keys":["ffA11Priority","ffA11Route","ffA11Template","ffA11TemplateName","ffA11TemplateSave","ffA11TemplateDelete","ffA11Preview","ffA11GrantUser","ffA11GrantRole","ffA11GrantBranch","ffA11GrantSave","ffA11GrantRefresh","ffA11Audit"],"styleOnly":true},"order_customer_modal":{"screen":"orders","keys":["ffCustomerEditSave","ffCustomerEditCancel"],"styleOnly":true},"order_picker_modal":{"screen":"orders","keys":["ffUnifiedMenuReview","ffUnifiedMenuUndo","ffUnifiedMenuClose"],"styleOnly":true}}'; g record; rows jsonb; patch jsonb; invalid jsonb;
BEGIN
 FOR g IN SELECT * FROM jsonb_each(spec) LOOP
 SELECT jsonb_agg(jsonb_build_object('key',k,'shape','pack','size','normal','align','center') ORDER BY ord) INTO rows FROM jsonb_array_elements_text(g.value->'keys') WITH ORDINALITY a(k,ord);
 patch:=jsonb_build_object(g.key,rows);
 IF NOT ff_private.a07_valid_elements(patch,g.value->>'screen') THEN RAISE EXCEPTION 'new component %',g.key;END IF;
 IF ff_private.a07_valid_elements(patch,CASE WHEN g.value->>'screen'='finance' THEN 'driver' ELSE 'finance' END) OR ff_private.a07_valid_elements(jsonb_build_object(g.key,jsonb_set(rows,'{0,key}','"unknown_unsafe"')),g.value->>'screen') THEN RAISE EXCEPTION 'scope/key violation %',g.key;END IF;
 invalid:=jsonb_build_object(g.key,jsonb_set(rows,'{0,align}','"end"'));
 IF ff_private.a09_merge_elements(g.value->>'screen',patch,patch,invalid,ARRAY['layout','buttons','colors']) IS NOT NULL THEN RAISE EXCEPTION 'delegation bypass %',g.key;END IF;
 END LOOP;
END $qa$;
SELECT 'PASS STEP03 83 dynamic component and modal keys' AS result;
ROLLBACK;